<script setup>
import {computed,ref} from 'vue';
import FormDialog from './FormDialog.vue';
import {farmQuantity} from '../services/farms.js';
defineEmits(['close','edit','care']);const props=defineProps({label:String,scope:String,data:Object,loading:Boolean,error:String,canEdit:Boolean,care:Boolean});
const search=ref(''),page=ref(1),money=value=>Number(value||0).toLocaleString('es-ES',{style:'currency',currency:'EUR'});
const lines=computed(()=>{const text=search.value.toLocaleLowerCase('es');return(props.data?.lines||[]).filter(row=>!text||[row.description,row.reference,row.farm_name,row.lot_code].some(value=>String(value||'').toLocaleLowerCase('es').includes(text)));});
const visible=computed(()=>lines.value.slice((page.value-1)*25,page.value*25)),pages=computed(()=>Math.max(1,Math.ceil(lines.value.length/25)));
</script>
<template><FormDialog :title="'Detalle de gastos · '+label" :busy="loading" @close="$emit('close')"><p class="muted">{{ scope }}</p><p v-if="loading" role="status">Cargando detalle…</p><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><template v-if="data"><div class="detail-heading"><strong>Total {{ label }}: {{ money(data.totals.base) }}</strong><button v-if="care" class="button primary" :disabled="!canEdit" @click="$emit('care')">Registrar cuido</button></div><label for="expense-detail-search">Buscar en el detalle<input id="expense-detail-search" v-model="search" type="search" @input="page=1"></label><div class="table-wrap detail-table"><table><thead><tr><th>Fecha / documento</th><th>Granja / lote</th><th>Concepto</th><th class="number">Unidades</th><th class="number">Sin IVA</th><th class="number">IVA</th><th></th></tr></thead><tbody><tr v-for="row in visible" :key="(row.source_kind||'invoice')+'-'+row.id" @click="$emit('edit',row)"><td><button class="detail-link" @click.stop="$emit('edit',row)">{{ row.invoice_date }}<br>{{ row.reference }}</button></td><td>{{ row.farm_name||'Sin granja' }}<small>{{ row.lot_code||'Sin lote' }}</small></td><td>{{ row.description }}</td><td class="number">{{ farmQuantity(row.quantity) }}</td><td class="number">{{ money(row.base_amount) }}</td><td class="number">{{ money(row.vat_amount) }}</td><td><button class="button" @click.stop="$emit('edit',row)">Ver detalle</button></td></tr><tr v-if="!lines.length"><td colspan="7">No hay gastos de este tipo en el ámbito seleccionado.</td></tr></tbody></table></div><div class="actions detail-pages"><button class="button" :disabled="page<=1" @click="page--">Anterior</button><span>{{ page }} / {{ pages }} · {{ lines.length }} líneas</span><button class="button" :disabled="page>=pages" @click="page++">Siguiente</button></div></template></FormDialog></template>
<style scoped>.detail-heading{display:flex;justify-content:space-between;align-items:center;margin:20px 0;gap:15px;flex-wrap:wrap}.detail-table{max-height:55vh;margin:18px 0}.detail-table table{width:100%}.detail-table tr{cursor:pointer}.detail-table tr:hover{background:var(--primary-soft)}.detail-table small{display:block;color:#65748a}.number{text-align:right;white-space:nowrap}.detail-link{border:0;background:none;color:var(--primary);text-align:left;cursor:pointer;font:inherit;padding:0;text-decoration:underline}.detail-pages{justify-content:center}</style>
